INSERT INTO `tbl_rooms` VALUES (1,'038139',20,1,'public',1,10,'[{\"id\":\"72\",\"category\":\"1\",\"subcategory\":\"6\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Medeni Kanun\'un kabul edilmesiyle (17 \\u015eubat 1926) T\\u00fcrk kad\\u0131n\\u0131na a\\u015fa\\u011f\\u0131daki haklardan hangisi VER\\u0130LMEM\\u0130\\u015eT\\u0130R?\",\"question_type\":\"1\",\"optiona\":\"Se\\u00e7me ve Se\\u00e7ilme Hakk\\u0131\",\"optionb\":\"Miras E\\u015fitli\\u011fi\",\"optionc\":\"Mahkemede Tan\\u0131kl\\u0131k E\\u015fitli\\u011fi\",\"optiond\":\"Bo\\u015fanma Hakk\\u0131\",\"optione\":\"\\u0130stedi\\u011fi Mesle\\u011fe Girme Hakk\\u0131\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Kad\\u0131nlara siyasi haklar (se\\u00e7me-se\\u00e7ilme) 1930 (Belediye), 1933 (Muhtar) ve 1934\'te (Milletvekili) verilmi\\u015ftir.\"},{\"id\":\"161\",\"category\":\"1\",\"subcategory\":\"3\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"\\u0130stanbul\'un fethinin d\\u00fcnya tarihi a\\u00e7\\u0131s\\u0131ndan en \\u00f6nemli sonucu a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Orta \\u00c7a\\u011f\'\\u0131n kapan\\u0131p Yeni \\u00c7a\\u011f\'\\u0131n ba\\u015flamas\\u0131\",\"optionb\":\"\\u0130pek Yolu\'nun kontrol\\u00fcn\\u00fcn ge\\u00e7mesi\",\"optionc\":\"Fener Rum Patrikhanesi\'nin himaye edilmesi\",\"optiond\":\"Toplar\\u0131n surlar\\u0131 y\\u0131kabilece\\u011finin g\\u00f6r\\u00fclmesi\",\"optione\":\"Bizans\'\\u0131n y\\u0131k\\u0131lmas\\u0131\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"\\u0130stanbul\'un fethi evrensel \\u00f6l\\u00e7ekte Orta \\u00c7a\\u011f\'\\u0131 bitirip Yeni \\u00c7a\\u011f\'\\u0131 ba\\u015flatm\\u0131\\u015ft\\u0131r.\"},{\"id\":\"46\",\"category\":\"1\",\"subcategory\":\"3\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Bug\\u00fcnk\\u00fc T\\u00fcrkiye-\\u0130ran s\\u0131n\\u0131r\\u0131n\\u0131n temelini b\\u00fcy\\u00fck \\u00f6l\\u00e7\\u00fcde belirleyen 1639 tarihli antla\\u015fma hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Kasr-\\u0131 \\u015eirin Antla\\u015fmas\\u0131\",\"optionb\":\"Ferhat Pa\\u015fa Antla\\u015fmas\\u0131\",\"optionc\":\"Amasya Antla\\u015fmas\\u0131\",\"optiond\":\"Nasuh Pa\\u015fa Antla\\u015fmas\\u0131\",\"optione\":\"Buca\\u015f Antla\\u015fmas\\u0131\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"IV. Murat\'\\u0131n Ba\\u011fdat Seferi sonras\\u0131 imzalanan Kasr-\\u0131 \\u015eirin Antla\\u015fmas\\u0131 bug\\u00fcnk\\u00fc s\\u0131n\\u0131r\\u0131n temelidir.\"},{\"id\":\"171\",\"category\":\"1\",\"subcategory\":\"4\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Osmanl\\u0131 Devleti\'nde Kap\\u0131kulu Ocaklar\\u0131na asker yeti\\u015ftirmek amac\\u0131yla gayrim\\u00fcslim \\u00e7ocuklar\\u0131n toplan\\u0131p e\\u011fitilmesi sistemine ne ad verilir?\",\"question_type\":\"1\",\"optiona\":\"Dev\\u015firme Sistemi\",\"optionb\":\"T\\u0131mar Sistemi\",\"optionc\":\"\\u0130ltizam Sistemi\",\"optiond\":\"Malikane Sistemi\",\"optione\":\"M\\u00fcsadere Sistemi\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Dev\\u015firme sistemi ile Acemi Oca\\u011f\\u0131 ve Enderun Mektebi\'ne asker ve devlet adam\\u0131 yeti\\u015ftirilmi\\u015ftir.\"},{\"id\":\"73\",\"category\":\"1\",\"subcategory\":\"6\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"T\\u00fcrkiye Cumhuriyeti\'nin ilk muhalefet partisi a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Terakkiperver Cumhuriyet F\\u0131rkas\\u0131\",\"optionb\":\"Serbest Cumhuriyet F\\u0131rkas\\u0131\",\"optionc\":\"Demokrat Parti\",\"optiond\":\"Milli Kalk\\u0131nma Partisi\",\"optione\":\"Halk F\\u0131rkas\\u0131\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"1924 y\\u0131l\\u0131nda Kaz\\u0131m Karabekir, Rauf Orbay ve Ali Fuat Cebesoy taraf\\u0131ndan kurulmu\\u015ftur.\"},{\"id\":\"155\",\"category\":\"1\",\"subcategory\":\"2\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Anadolu\'da kurulan ilk T\\u00fcrk beyli\\u011fi a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Saltuklular\",\"optionb\":\"Dani\\u015fmentliler\",\"optionc\":\"Meng\\u00fccekliler\",\"optiond\":\"Artuklular\",\"optione\":\"\\u00c7aka Beyli\\u011fi\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Erzurum ve \\u00e7evresinde kurulan Saltuklular, Malazgirt sonras\\u0131 kurulan ilk T\\u00fcrk beyli\\u011fidir.\"},{\"id\":\"59\",\"category\":\"1\",\"subcategory\":\"5\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Manda ve himayenin kesin olarak reddedildi\\u011fi ve t\\u00fcm cemiyetlerin tek \\u00e7at\\u0131 alt\\u0131nda birle\\u015ftirildi\\u011fi kongre hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Sivas Kongresi\",\"optionb\":\"Erzurum Kongresi\",\"optionc\":\"Havza Genelgesi\",\"optiond\":\"Afyon Kongresi\",\"optione\":\"Pozant\\u0131 Kongresi\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Sivas Kongresi\'nde manda kesin reddedilmi\\u015f ve cemiyetler Anadolu ve Rumeli M\\u00fcdafaa-i Hukuk Cemiyeti ad\\u0131yla birle\\u015ftirilmi\\u015ftir.\"},{\"id\":\"156\",\"category\":\"1\",\"subcategory\":\"2\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Anadolu\'nun T\\u00fcrk yurdu oldu\\u011funu kesinle\\u015ftiren ve Bizans\'\\u0131n T\\u00fcrkleri Anadolu\'dan atma \\u00fcmidini bitiren sava\\u015f hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Miryokefalon Sava\\u015f\\u0131 (1176)\",\"optionb\":\"Malazgirt Sava\\u015f\\u0131 (1071)\",\"optionc\":\"Pasinler Sava\\u015f\\u0131 (1048)\",\"optiond\":\"Dandanakan Sava\\u015f\\u0131 (1040)\",\"optione\":\"Yass\\u0131\\u00e7emen Sava\\u015f\\u0131 (1230)\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"II. K\\u0131l\\u0131\\u00e7 Arslan komutas\\u0131nda kazan\\u0131lan Miryokefalon Sava\\u015f\\u0131 ile Anadolu kesin olarak T\\u00fcrk yurdu olmu\\u015ftur.\"},{\"id\":\"1\",\"category\":\"1\",\"subcategory\":\"1\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"\\u0130slamiyet \\u00f6ncesi T\\u00fcrk devletlerinde devlet i\\u015flerinin g\\u00f6r\\u00fc\\u015f\\u00fcl\\u00fcp karara ba\\u011fland\\u0131\\u011f\\u0131 meclise ne ad verilir?\",\"question_type\":\"1\",\"optiona\":\"Toy (Kurultay)\",\"optionb\":\"Tigin\",\"optionc\":\"\\u015ead\",\"optiond\":\"Tamgac\\u0131\",\"optione\":\"Yargu\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"\\u0130slamiyet \\u00f6ncesi T\\u00fcrklerde h\\u00fck\\u00fcmdar ba\\u015fkanl\\u0131\\u011f\\u0131nda toplanan dan\\u0131\\u015fma ve karar meclisine Toy veya Kurultay ad\\u0131 verilir.\"},{\"id\":\"152\",\"category\":\"1\",\"subcategory\":\"2\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Hicaz b\\u00f6lgesine (Mekke ve Medine) hakim olan ilk T\\u00fcrk devleti a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"\\u0130h\\u015fidiler (Ak\\u015fitler)\",\"optionb\":\"Toluno\\u011fullar\\u0131\",\"optionc\":\"Eyyubiler\",\"optiond\":\"B\\u00fcy\\u00fck Sel\\u00e7uklular\",\"optione\":\"Osmanl\\u0131 Devleti\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Muhammed bin To\\u011fa\\u00e7 taraf\\u0131ndan kurulan \\u0130h\\u015fidiler Kutsal Topraklara hakim olan ilk T\\u00fcrk devletidir.\"}]','2026-09-06 23:06:50',0,0,0,0),(2,'034988',10,1,'public',1,10,'[{\"id\":\"1102\",\"category\":\"1\",\"subcategory\":\"3\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2013 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nOsmanl\\u0131 toplumunda uzun y\\u0131llar Millet-i Sad\\u0131ka olarak bilinen Ermeni toplumunun isteklerinin zamanla bir soruna d\\u00f6n\\u00fc\\u015fmesinde a\\u015fa\\u011f\\u0131dakilerden hangisinin etkili oldu\\u011fu savunulamaz?\",\"question_type\":\"1\",\"optiona\":\"Avrupa devletlerinin k\\u0131\\u015fk\\u0131rtmac\\u0131 politikas\\u0131\",\"optionb\":\"Frans\\u0131z ihtilal\\u0131yla geli\\u015fen milliyet\\u00e7ilik d\\u00fc\\u015f\\u00fcncesi\",\"optionc\":\"Balkanlarda oturan Hristiyan topluluklar\\u0131n ba\\u011f\\u0131ms\\u0131zl\\u0131klar\\u0131n\\u0131 kazanmas\\u0131\",\"optiond\":\"Rusya ve \\u0130ngiltere\\u2019nin, Ermenilerle ilgili \\u0131slahat yap\\u0131lmas\\u0131 i\\u00e7in Osmanl\\u0131 Devleti\'ne bask\\u0131 yapmas\\u0131\",\"optione\":\"Osmanl\\u0131 Devleti\\u2019nin, Osmanl\\u0131c\\u0131l\\u0131k fikrini uygulamaya koymas\\u0131\",\"answer\":\"e\",\"level\":\"1\",\"note\":\"2013 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"366\",\"category\":\"1\",\"subcategory\":\"6\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2021 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nElif, Atat\\u00fcrk D\\u00f6nemi\\u2019nde madencilik ve enerji i\\u015flerini y\\u00f6netmek amac\\u0131yla kurulmu\\u015f olan kurulu\\u015flar \\u00fczerine bir \\u00f6dev haz\\u0131rlamaktad\\u0131r. A\\u015fa\\u011f\\u0131dakilerden hangisi Elif\\u2019in haz\\u0131rlayaca\\u011f\\u0131 \\u00f6devde yer almal\\u0131d\\u0131r?\",\"question_type\":\"1\",\"optiona\":\"S\\u00fcmerbank\",\"optionb\":\"\\u0130\\u015f Bankas\\u0131\",\"optionc\":\"Etibank\",\"optiond\":\"Ziraat Bankas\\u0131\",\"optione\":\"Denizbank\",\"answer\":\"c\",\"level\":\"1\",\"note\":\"2021 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"47\",\"category\":\"1\",\"subcategory\":\"4\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Osmanl\\u0131 Devleti\'nde padi\\u015fahtan sonra en yetkili devlet adam\\u0131 ve padi\\u015fah\\u0131n mutlak vekili kimdir?\",\"question_type\":\"1\",\"optiona\":\"Sadrazam (Vezir-i Azam)\",\"optionb\":\"\\u015eeyh\\u00fclislam\",\"optionc\":\"Kazasker\",\"optiond\":\"Defterdar\",\"optione\":\"Ni\\u015fanc\\u0131\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Sadrazam padi\\u015fah\\u0131n m\\u00fchr\\u00fcn\\u00fc (m\\u00fchr-i h\\u00fcmayun) ta\\u015f\\u0131r ve padi\\u015fah ad\\u0131na devleti y\\u00f6netir.\"},{\"id\":\"895\",\"category\":\"1\",\"subcategory\":\"4\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2015 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nXIX. y\\u00fczy\\u0131l sonlar\\u0131nda geli\\u015fen; \\u00f6nc\\u00fcleri aras\\u0131nda Mehmet Emin Resulzade, Mahmut Celaleddin Pa\\u015fa ve Gasp\\u0131ral\\u0131 \\u0130smail Bey gibi ki\\u015filerin g\\u00f6sterildi\\u011fi; d\\u00fc\\u015f\\u00fcncelerini daha \\u00e7ok dil, k\\u00fclt\\u00fcr ve ekonomi meseleleri \\u00fczerinde yo\\u011funla\\u015ft\\u0131ran d\\u00fc\\u015f\\u00fcnce ak\\u0131m\\u0131 a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Bat\\u0131c\\u0131l\\u0131k\",\"optionb\":\"T\\u00fcrk\\u00e7\\u00fcl\\u00fck\",\"optionc\":\"\\u0130slamc\\u0131l\\u0131k\",\"optiond\":\"Ademimerkeziyet\\u00e7ilik\",\"optione\":\"Sosyalizm\",\"answer\":\"b\",\"level\":\"1\",\"note\":\"2015 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"1202\",\"category\":\"1\",\"subcategory\":\"2\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2012 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nSatuk Bu\\u011fra Han, amcas\\u0131 O\\u011fulcak Kad\\u0131r Han devletin ba\\u015f\\u0131ndayken \\u0130slamiyet\\u2019i benimsemi\\u015f, amcas\\u0131ndan sonra h\\u00fck\\u00fcmdar olunca da \\u0130slamiyet\\u2019i resm\\u00ee din olarak kabul etmi\\u015ftir. Bu bilgiyle Karahanl\\u0131larda, I. devleti y\\u00f6netme yetkisinin hanedana ait oldu\\u011fu, II. \\u0130slamiyet\\u2019in T\\u00fcrkler aras\\u0131nda yay\\u0131lmas\\u0131n\\u0131n h\\u0131zland\\u0131\\u011f\\u0131, III. Arap\\u00e7an\\u0131n resm\\u00ee dil olarak kabul edildi\\u011fi yarg\\u0131lar\\u0131ndan hangilerine ula\\u015f\\u0131labilir?\",\"question_type\":\"1\",\"optiona\":\"Yaln\\u0131z I\",\"optionb\":\"Yaln\\u0131z II\",\"optionc\":\"Yaln\\u0131z III\",\"optiond\":\"I ve II\",\"optione\":\"I, II ve III\",\"answer\":\"d\",\"level\":\"1\",\"note\":\"2012 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"1225\",\"category\":\"1\",\"subcategory\":\"6\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2012 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nMustafa Kemal Pa\\u015fa\\u2019n\\u0131n Nutuk\\u2019unda, I. TBMM\\u2019nin a\\u00e7\\u0131lmas\\u0131, II. Halifeli\\u011fin kald\\u0131r\\u0131lmas\\u0131, III. Serbest Cumhuriyet Partisinin kurulmas\\u0131 olaylar\\u0131ndan hangileri yer almaktad\\u0131r?\",\"question_type\":\"1\",\"optiona\":\"Yaln\\u0131z I\",\"optionb\":\"Yaln\\u0131z II\",\"optionc\":\"Yaln\\u0131z III\",\"optiond\":\"I ve II\",\"optione\":\"I, II ve III\",\"answer\":\"d\",\"level\":\"1\",\"note\":\"2012 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"453\",\"category\":\"1\",\"subcategory\":\"2\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2020 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nT\\u00fcrkiye Sel\\u00e7uklu Devleti\\u2019nin ba\\u015fkenti \\u0130znik\\u2019in Ha\\u00e7l\\u0131 Ordusu ele ge\\u00e7irilmesi \\u00fczerine ba\\u015fkentin Konya\\u2019ya ta\\u015f\\u0131nmas\\u0131, a\\u015fa\\u011f\\u0131daki h\\u00fck\\u00fcmdarlar\\u0131n hangisi d\\u00f6neminde ger\\u00e7ekle\\u015fmi\\u015ftir?\",\"question_type\":\"1\",\"optiona\":\"I. K\\u0131l\\u0131\\u00e7 Arslan\",\"optionb\":\"I. Mesut\",\"optionc\":\"I. Al\\u00e2eddin Keykubat\",\"optiond\":\"I. G\\u0131yaseddin Keyh\\u00fcsrev\",\"optione\":\"I. \\u0130zzettin Keykavus\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"2020 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"1318\",\"category\":\"1\",\"subcategory\":\"3\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2010 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nXIX. y\\u00fczy\\u0131l\\u0131n ortalar\\u0131ndan itibaren Sanayi \\u0130nk\\u0131lab\\u0131, Os- manl\\u0131 Devleti\\u2019nde esnaf te\\u015fkilat\\u0131n\\u0131 etkilemi\\u015f ve esna- f\\u0131n \\u00fcretimdeki \\u00f6nemi azalm\\u0131\\u015ft\\u0131r. A\\u015fa\\u011f\\u0131dakilerden hangisinin bu durumla ilgili ge- li\\u015fmelerden biri oldu\\u011fu savunulamaz?\",\"question_type\":\"1\",\"optiona\":\"\\u0130thalat\\u0131n azalmas\\u0131\",\"optionb\":\"\\u0130\\u015fsizli\\u011fin artmas\\u0131\",\"optionc\":\"Paran\\u0131n de\\u011ferinin d\\u00fc\\u015fmesi\",\"optiond\":\"Yerli mal\\u0131n i\\u00e7 pazarda s\\u00fcr\\u00fcm\\u00fcn\\u00fcn azalmas\\u0131\",\"optione\":\"\\u00dcretimde kullan\\u0131lan ham maddenin d\\u0131\\u015far\\u0131ya \\u00e7\\u0131k- mas\\u0131\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"2010 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"},{\"id\":\"127\",\"category\":\"1\",\"subcategory\":\"3\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"Osmanl\\u0131 Devleti\'nde ilk alt\\u0131n para Fatih Sultan Mehmet d\\u00f6neminde bas\\u0131lm\\u0131\\u015ft\\u0131r.\",\"question_type\":\"2\",\"optiona\":\"Do\\u011fru\",\"optionb\":\"Yanl\\u0131\\u015f\",\"optionc\":\"\",\"optiond\":\"\",\"optione\":\"\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"Do\\u011fru. \'Sultani\' ad\\u0131 verilen ilk alt\\u0131n para Fatih d\\u00f6neminde bas\\u0131lm\\u0131\\u015ft\\u0131r.\"},{\"id\":\"472\",\"category\":\"1\",\"subcategory\":\"6\",\"language_id\":\"52\",\"image\":\"\",\"question\":\"[2020 KPSS \\u00c7\\u0131km\\u0131\\u015f Soru]\\n\\nA\\u015fa\\u011f\\u0131dakilerden hangisi, 1924 Anayasas\\u0131\\u2019na sonraki y\\u0131llarda eklenen konulardan biridir?\",\"question_type\":\"1\",\"optiona\":\"Egemenli\\u011fin millete ait oldu\\u011funun vurgulanmas\\u0131\",\"optionb\":\"Ankara\\u2019n\\u0131n ba\\u015fkent oldu\\u011funun belirtilmesi\",\"optionc\":\"T\\u00fcrk\\u00e7enin resm\\u00ee dil olarak kabul edilmesi\",\"optiond\":\"Kad\\u0131nlara se\\u00e7me ve se\\u00e7ilme hakk\\u0131 verilmesi\",\"optione\":\"T\\u00fcrk vatanda\\u015fl\\u0131\\u011f\\u0131 tan\\u0131m\\u0131n\\u0131n yap\\u0131lmas\\u0131\",\"answer\":\"d\",\"level\":\"1\",\"note\":\"2020 KPSS Lisans Genel K\\u00fclt\\u00fcr oturumunda \\u00d6SYM taraf\\u0131ndan sorulmu\\u015f orijinal \\u00e7\\u0131km\\u0131\\u015f s\\u0131nav sorusudur.\"}]','2026-09-08 14:47:58',0,0,0,0),(3,'170056',20,1,'public',44,10,'[{\"id\":\"1719\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"A\\u015fa\\u011f\\u0131daki c\\u00fcmlelerin hangisinde y\\u00fcklemi zaman y\\u00f6n\\u00fcnden tamamlayan bir \\u00f6ge kullan\\u0131lmam\\u0131\\u015ft\\u0131r?\",\"question_type\":\"1\",\"optiona\":\"Tedaviye ba\\u015flanmadan \\u00f6nce hastan\\u0131n kilosu sabitlenmelidir.\",\"optionb\":\"Hasta tedavi edilirken robot destekli sistemler tercih edilebilir.\",\"optionc\":\"Tedavi tamamland\\u0131ktan sonra hastan\\u0131n durumu bir s\\u00fcre g\\u00f6zlemlenir.\",\"optiond\":\"Baz\\u0131 yenilikler ilk ba\\u015flarda herkes taraf\\u0131ndan anla\\u015f\\u0131lamayabilir.\",\"optione\":\"Do\\u011fal tedavi y\\u00f6ntemleri \\u00fclkemizde yayg\\u0131n olarak kullan\\u0131l\\u0131r.\",\"answer\":\"b\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 9. Soru. Resmi Do\\u011fru Cevap: B\"},{\"id\":\"1835\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"T\\u0131bb\\u0131n \\u00f6nemli bulu\\u015f ve geli\\u015fmelerinden biri a\\u015f\\u0131lard\\u0131r. A\\u015f\\u0131lama y\\u00f6ntemi, a\\u015f\\u0131s\\u0131 bulunan hastal\\u0131klardan korunmada, ba\\u015fvurulan en \\u00f6nemli halk sa\\u011fl\\u0131\\u011f\\u0131 uygulamas\\u0131d\\u0131r. Her y\\u0131l d\\u00fcnyada 5 ya\\u015f\\u0131n alt\\u0131nda 12 milyon \\u00e7ocuk ya\\u015fam\\u0131n\\u0131 yitirmekteyken son zamanlarda d\\u00fczenli olarak uygulanan a\\u015f\\u0131lar sayesinde 3 milyon \\u00e7ocu\\u011fun \\u00f6l\\u00fcm\\u00fc \\u00f6nlenmi\\u015f ve 750 bin \\u00e7ocuk da sakatl\\u0131ktan korunmu\\u015ftur. Bug\\u00fcne de\\u011fin a\\u015f\\u0131lama ile \\u00e7i\\u00e7ek hastal\\u0131\\u011f\\u0131 gibi baz\\u0131 hastal\\u0131klar\\u0131n k\\u00f6k\\u00fc kaz\\u0131nm\\u0131\\u015ft\\u0131r. \\u00c7ocuk felci ve k\\u0131zam\\u0131k hastal\\u0131\\u011f\\u0131na ili\\u015fkin \\u00e7al\\u0131\\u015fmalar ise devam etmektedir. Yeni do\\u011fan bebeklere uygulanan BCG a\\u015f\\u0131s\\u0131 ile menenjit ve t\\u00fcberk\\u00fcloz gibi hastal\\u0131klar\\u0131n g\\u00f6r\\u00fclme s\\u0131kl\\u0131\\u011f\\u0131nda d\\u00fc\\u015f\\u00fc\\u015f g\\u00f6zlemlenmi\\u015ftir. Bu par\\u00e7ada a\\u015fa\\u011f\\u0131dakilerden hangisine de\\u011finilmemi\\u015ftir?\",\"question_type\":\"1\",\"optiona\":\"Hastal\\u0131klar\\u0131n \\u00e7ocuklarda kal\\u0131c\\u0131 sa\\u011fl\\u0131k sorunlar\\u0131na yol a\\u00e7abildi\\u011fine\",\"optionb\":\"G\\u00fcn\\u00fcm\\u00fczde baz\\u0131 hastal\\u0131klar\\u0131n a\\u015f\\u0131 \\u00e7al\\u0131\\u015fmalar\\u0131n\\u0131n hen\\u00fcz tamamlanmad\\u0131\\u011f\\u0131na\",\"optionc\":\"A\\u015f\\u0131lar\\u0131n hangi ya\\u015f aral\\u0131\\u011f\\u0131ndaki \\u00e7ocuklara yapt\\u0131r\\u0131lmas\\u0131 gerekti\\u011fine\",\"optiond\":\"A\\u015f\\u0131lar sayesinde d\\u00fcnya genelinde \\u00e7ocuk \\u00f6l\\u00fcmlerinin azald\\u0131\\u011f\\u0131na\",\"optione\":\"A\\u015f\\u0131lama sonras\\u0131nda baz\\u0131 hastal\\u0131klara art\\u0131k rastlanmad\\u0131\\u011f\\u0131na\",\"answer\":\"c\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 21. Soru. Resmi Do\\u011fru Cevap: C\"},{\"id\":\"1510\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Latince ad\\u0131 \\u201cRhus Coridria\\u201d olan sumak, Toroslar\\u0131n k\\u0131y\\u0131dan uzak kesimlerinde yeti\\u015fen, k\\u0131\\u015f\\u0131n yapraklar\\u0131n\\u0131 d\\u00f6ken, \\u00e7al\\u0131 g\\u00f6r\\u00fcn\\u00fcml\\u00fc bir bitkidir. Yapraklar\\u0131 uzun, sivri ve t\\u00fcyl\\u00fcd\\u00fcr. \\u00dcz\\u00fcm salk\\u0131m\\u0131na benzeyen \\u00e7i\\u00e7ekleri, sonbahara do\\u011fru, k\\u0131z\\u0131la \\u00e7alan k\\u0131rm\\u0131z\\u0131 mercime\\u011fe benzer meyvelere d\\u00f6n\\u00fc\\u015f\\u00fcr. Meyveler toplan\\u0131r, kurutulur, sonra da \\u00f6\\u011f\\u00fct\\u00fcl\\u00fcr. Elde edilen toz, baharat olarak kullan\\u0131l\\u0131r. Suma\\u011f\\u0131n, i\\u015ftah\\u0131 a\\u00e7mas\\u0131n\\u0131n yan\\u0131 s\\u0131ra, sindirimi de kolayla\\u015ft\\u0131rd\\u0131\\u011f\\u0131 s\\u00f6ylenir. Bu par\\u00e7ada sumakla ilgili olarak a\\u015fa\\u011f\\u0131dakilerden hangisine de\\u011finilmemi\\u015ftir?\",\"question_type\":\"1\",\"optiona\":\"Yurdumuzun hangi b\\u00f6lgesinde yeti\\u015fti\\u011fine\",\"optionb\":\"Belli ba\\u015fl\\u0131 \\u00f6zelliklerinin neler oldu\\u011funa\",\"optionc\":\"Hangi \\u00f6zelli\\u011finin bir ba\\u015fka bitkiye benzedi\\u011fine\",\"optiond\":\"\\u0130la\\u00e7 yap\\u0131m\\u0131nda kullan\\u0131ld\\u0131\\u011f\\u0131na\",\"optione\":\"Baharat olarak kullan\\u0131labilmesi i\\u00e7in ne t\\u00fcr i\\u015flemlerden ge\\u00e7irildi\\u011fine\",\"answer\":\"d\",\"level\":\"1\",\"note\":\"\\u00d6SYM 2010 KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 26. Soru. Resmi Do\\u011fru Cevap: D\"},{\"id\":\"1486\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Bug\\u00fcne de\\u011fin hi\\u00e7 ayn\\u0131 ortamda \\u00e7al\\u0131\\u015fmad\\u0131k. Ama \\u00e7al\\u0131\\u015fma disiplini ve i\\u015findeki ba\\u015far\\u0131s\\u0131 a\\u00e7\\u0131s\\u0131ndan yerinde de\\u011fil de yan\\u0131nda olmay\\u0131 istedi\\u011fim say\\u0131l\\u0131 ki\\u015filerden biridir o. Bu c\\u00fcmledeki alt\\u0131 \\u00e7izili s\\u00f6zle anlat\\u0131lmak istenen a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Say\\u0131p sevmek\",\"optionb\":\"Onun gibi davranmak\",\"optionc\":\"Birlikte \\u00e7al\\u0131\\u015fmak\",\"optiond\":\"\\u00d6rnek g\\u00f6stermek\",\"optione\":\"D\\u00fc\\u015f\\u00fcncesini sorgulamak\",\"answer\":\"c\",\"level\":\"1\",\"note\":\"\\u00d6SYM 2010 KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 1. Soru. Resmi Do\\u011fru Cevap: C\"},{\"id\":\"1841\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Buna g\\u00f6re; I. Ay\\u015fe, II. Burak, III. Cemil adl\\u0131 ki\\u015filerden hangileri M adl\\u0131 besteciye ait bir \\u015fark\\u0131 s\\u00f6ylemi\\u015f olabilir?\",\"question_type\":\"1\",\"optiona\":\"Yaln\\u0131z I\",\"optionb\":\"Yaln\\u0131z II\",\"optionc\":\"Yaln\\u0131z III\",\"optiond\":\"I ve II\",\"optione\":\"II ve III\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 27. Soru. Resmi Do\\u011fru Cevap: A\"},{\"id\":\"1733\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Bu par\\u00e7ada s\\u00f6z\\u00fc edilen yazara g\\u00f6re ada kavram\\u0131n\\u0131n temel niteli\\u011fi a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"\\u00c7a\\u011fr\\u0131\\u015f\\u0131m alanlar\\u0131n\\u0131n s\\u0131n\\u0131rl\\u0131l\\u0131\\u011f\\u0131\",\"optionb\":\"Ger\\u00e7ekli\\u011fi yans\\u0131tmadaki yetersizli\\u011fi\",\"optionc\":\"D\\u0131\\u015f d\\u00fcnyadan yal\\u0131t\\u0131lm\\u0131\\u015fl\\u0131\\u011f\\u0131\",\"optiond\":\"Anlam\\u0131n\\u0131n de\\u011fi\\u015fmezli\\u011fi\",\"optione\":\"Tan\\u0131mlanmas\\u0131n\\u0131n zorlu\\u011fu\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 25. Soru. Resmi Do\\u011fru Cevap: A\"},{\"id\":\"1825\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Mehmet k\\u0131zd\\u0131 ( ) ( ) Tam da a\\u011flayacak s\\u0131ray\\u0131 buldun ( ) de\\u011fil mi ( ) ( ) dedi. Bu c\\u00fcmlede ayra\\u00e7larla ( ) belirtilen yerlere s\\u0131ras\\u0131yla a\\u015fa\\u011f\\u0131daki noktalama i\\u015faretlerinden hangileri getirilmelidir?\",\"question_type\":\"1\",\"optiona\":\"(:) (\\u201c) (,) (?) (\\u201d)\",\"optionb\":\"(;) (\\u201c) (...) (?) (\\u201d)\",\"optionc\":\"(.) (-) (.) (?) (,)\",\"optiond\":\"(.) (\\u201c) (,) (\\u201d) (?)\",\"optione\":\"(:) (\\u201c) (...) (?) (\\u201d)\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 11. Soru. Resmi Do\\u011fru Cevap: A\"},{\"id\":\"1844\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Ay\\u015fe ve Burak\'\\u0131n ayn\\u0131 bestecinin \\u015fark\\u0131lar\\u0131n\\u0131 s\\u00f6yledikleri biliniyorsa a\\u015fa\\u011f\\u0131dakilerden hangisi do\\u011frudur?\",\"question_type\":\"1\",\"optiona\":\"Cemil ve Defne ayn\\u0131 bestecinin \\u015fark\\u0131lar\\u0131n\\u0131 s\\u00f6ylemi\\u015ftir.\",\"optionb\":\"Ay\\u015fe ve Erdem farkl\\u0131 bestecilerin \\u015fark\\u0131lar\\u0131n\\u0131 s\\u00f6ylemi\\u015ftir.\",\"optionc\":\"Burak ve Cemil ayn\\u0131 bestecinin \\u015fark\\u0131lar\\u0131n\\u0131 s\\u00f6ylemi\\u015ftir.\",\"optiond\":\"Defne ve Gizem farkl\\u0131 bestecilerin \\u015fark\\u0131lar\\u0131n\\u0131 s\\u00f6ylemi\\u015ftir.\",\"optione\":\"Funda ve Gizem ayn\\u0131 bestecinin \\u015fark\\u0131lar\\u0131n\\u0131 s\\u00f6ylemi\\u015ftir.\",\"answer\":\"a\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 30. Soru. Resmi Do\\u011fru Cevap: A\"},{\"id\":\"1620\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"Hayat bir sorunlar yuma\\u011f\\u0131n\\u0131n i\\u00e7inde \\u00e7\\u0131rp\\u0131nmayla ge\\u00e7iyor. Kimi insanlar, sorunlarla bo\\u011fu\\u015ftuk\\u00e7a i\\u015fi i\\u00e7inden \\u00e7\\u0131k\\u0131lmaz h\\u00e2le getirirken baz\\u0131lar\\u0131 sorunlar\\u0131 \\u00e2deta tereya\\u011f\\u0131ndan k\\u0131l \\u00e7eker gibi \\u00e7\\u00f6z\\u00fcyor. Sorunlar\\u0131 \\u00e7\\u00f6zmenin en temel ilkesi, onu fark etti\\u011fimiz ana kadarki bak\\u0131\\u015f a\\u00e7\\u0131m\\u0131z\\u0131 sorgulamak ve kendimizi farkl\\u0131 bir bi\\u00e7imde d\\u00fc\\u015f\\u00fcnmeye zorlamakt\\u0131r. Bu par\\u00e7ada as\\u0131l anlat\\u0131lmak istenen a\\u015fa\\u011f\\u0131dakilerden hangisidir?\",\"question_type\":\"1\",\"optiona\":\"Bak\\u0131\\u015f a\\u00e7\\u0131s\\u0131n\\u0131 s\\u00fcrekli de\\u011fi\\u015ftirmek sorunlar\\u0131n g\\u00f6r\\u00fclmesini engeller.\",\"optionb\":\"Sorunlar\\u0131 \\u00e7\\u00f6zmek i\\u00e7in sebeplerinin ortadan kald\\u0131r\\u0131lmas\\u0131 gerekir.\",\"optionc\":\"Soruna nereden yakla\\u015ft\\u0131\\u011f\\u0131n\\u0131z, sorunun \\u00e7\\u00f6z\\u00fcm\\u00fcnde belirleyicidir.\",\"optiond\":\"Sorunlar\\u0131 kolayca \\u00e7\\u00f6zmek herkes i\\u00e7in geli\\u015ftirilebilir bir beceridir.\",\"optione\":\"Sorunun kendisini fark edip anlamak \\u00e7\\u00f6z\\u00fcm\\u00fcn ba\\u015flang\\u0131c\\u0131d\\u0131r.\",\"answer\":\"c\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 17. Soru. Resmi Do\\u011fru Cevap: C\"},{\"id\":\"1717\",\"category\":\"44\",\"subcategory\":\"67\",\"language_id\":\"66\",\"image\":\"\",\"question\":\"(I) Botanikte pistacia lentiscus ad\\u0131 verilen sak\\u0131z a\\u011fac\\u0131n\\u0131n kendine has pek \\u00e7ok \\u00f6zelli\\u011fi var. (II) Her \\u015feyden \\u00f6nce \\u00e7ok g\\u00fc\\u00e7l\\u00fc oldu\\u011fu i\\u00e7in sonbahar veya k\\u0131\\u015f \\u015fartlar\\u0131 onu etkilemiyor. (III) Yaz k\\u0131\\u015f yapra\\u011f\\u0131n\\u0131 d\\u00f6km\\u00fcyor, koruyor, dolay\\u0131s\\u0131yla da \\u00fc\\u015f\\u00fcm\\u00fcyor. (IV) \\u00c7ok se\\u00e7ici, \\u00f6yle her iklimde ve toprakta yeti\\u015fmiyor. (V) Kalabal\\u0131\\u011f\\u0131 sevmiyor, bir bah\\u00e7ede kendi ba\\u015f\\u0131na g\\u00f6\\u011fe y\\u00fckselmeyi tercih ediyor. Bu par\\u00e7adaki numaralanm\\u0131\\u015f c\\u00fcmlelerin hangisinde \\u00fcns\\u00fcz yumu\\u015famas\\u0131na u\\u011fram\\u0131\\u015f s\\u00f6zc\\u00fck yoktur?\",\"question_type\":\"1\",\"optiona\":\"I.\",\"optionb\":\"II.\",\"optionc\":\"III.\",\"optiond\":\"IV.\",\"optione\":\"V.\",\"answer\":\"d\",\"level\":\"1\",\"note\":\"\\u00d6SYM KPSS Orta\\u00f6\\u011fretim (Lise) Genel Yetenek (T\\u00fcrk\\u00e7e) 7. Soru. Resmi Do\\u011fru Cevap: D\"}]','2026-09-08 17:27:57',0,0,0,0);
